tracks
            .iter()
            .map(|t| {
                let name = t.get("name").and_then(Value::as_str).unwrap_or_default();
                let plugins = match t.get("plugins") {
                    Some(Value::Object(p)) => p
                        .iter()
                        .filter(|(_, v)| v.is_object())
                        .map(|(id, v)| (id.clone(), v.to_string()))
                        .collect(),
                    _ => BTreeMap::new(),
                };
                TrackEntry {
                    name: name.to_owned(),
                    plugins,
                }
            }).collect

